import random
from fractions import Fraction

def calculate_circuit_depth(cnf):
    n = len(cnf)
    assignment = {}

    def dpll(cnf, assignment):
        if not cnf:
            return True
        unit_clause = next((c for c in cnf if len(c) == 1), None)
        if unit_clause:
            literal = unit_clause[0]
            if literal < 0 and -literal in assignment:
                return False
            assignment[literal] = True
            cnf = [c for c in cnf if literal not in c and -literal not in c]
            return dpll(cnf, assignment)
        pure_literal = next((l for l in range(1, n + 1) if (l not in assignment and -l not in assignment)), None)
        if pure_literal:
            assignment[pure_literal] = True
            cnf = [c for c in cnf if pure_literal not in c and -pure_literal not in c]
            return dpll(cnf, assignment)
        literal = random.choice([l for l in range(1, n + 1) if l not in assignment and -l not in assignment])
        if dpll(cnf + [[-literal]], assignment):
            return True
        assignment[literal] = False
        return dpll(cnf + [[literal]], assignment)

    return len(dpll(cnf, assignment)) - 1

def calculate_entropy(state):
    n = len(state)
    counts = [0] * (n + 1)
    for q in state:
        counts[q] += 1
    probabilities = [Fraction(count, n) for count in counts]
    entropy = sum(-p * math.log2(p) for p in probabilities if p > 0)
    return entropy

